sp_FiltrarCliente	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_FiltrarCliente`(\n\n    IN Nome                 VARCHAR(200),\n\n    IN CpfCnpj              VARCHAR(20),\n\n    IN Email                VARCHAR(200),\n\n    IN TipoCliente          INT,\n\n    IN Genero               VARCHAR(10),\n\n    IN Estado               VARCHAR(2),\n\n    IN Cidade               VARCHAR(100),\n\n    IN FAtivo               TINYINT(1),\n\n    IN DthCadastroInicio    DATETIME,\n\n    IN DthCadastroFim       DATETIME,\n\n    IN DthNascimentoInicio  DATETIME,\n\n    IN DthNascimentoFim     DATETIME,\n\n    IN SemEmail             TINYINT(1),\n\n    IN AniversariantesDoMes TINYINT(1)\n\n)\nBEGIN\n\n    SELECT\n\n        c.idCliente, c.idEmpresa,\n\n        c.Nome AS nome, c.nomeFantasia, c.razaoSocial,\n\n        c.CNPJ_CPF AS cpfCNPJ, c.Email AS email, c.Telefone AS telefone,\n\n        c.tipoCliente_id, c.Observacao AS observacao, c.Genero AS genero,\n\n        c.enderecoId, c.dthCadastro, c.dthNascimento, c.fAtivo,\n\n        e.tipoEndereco, e.Logradouro AS logradouro, e.Numero AS numero,\n\n        e.Complemento AS complemento, e.Bairro AS bairro,\n\n        e.Cidade AS cidade, e.Estado AS estado, e.Pais AS pais, e.CEP AS cep\n\n    FROM Cliente c\n\n    LEFT JOIN Endereco e ON c.enderecoId = e.idEndereco\n\n    WHERE\n\n        (Nome     IS NULL OR c.Nome  LIKE CONCAT('%', Nome, '%'))\n\n        AND (CpfCnpj IS NULL OR REPLACE(REPLACE(REPLACE(c.CNPJ_CPF,'.',''),'-',''),'/','')\n\n                                LIKE CONCAT('%', REPLACE(REPLACE(REPLACE(CpfCnpj,'.',''),'-',''),'/',''), '%'))\n\n        AND (Email        IS NULL OR c.Email          LIKE CONCAT('%', Email, '%'))\n\n        AND (TipoCliente  IS NULL OR c.tipoCliente_id  = TipoCliente)\n\n        AND (Genero       IS NULL OR c.Genero          = Genero)\n\n        AND (Estado       IS NULL OR e.Estado          = Estado)\n\n        AND (Cidade       IS NULL OR e.Cidade         LIKE CONCAT('%', Cidade, '%'))\n\n        AND (FAtivo       IS NULL OR c.fAtivo          = FAtivo)\n\n        AND (DthCadastroInicio   IS NULL OR c.dthCadastro  >= DthCadastroInicio)\n\n        AND (DthCadastroFim      IS NULL OR c.dthCadastro  <  DATE_ADD(DthCadastroFim, INTERVAL 1 DAY))\n\n        AND (DthNascimentoInicio IS NULL OR c.dthNascimento >= DthNascimentoInicio)\n\n        AND (DthNascimentoFim    IS NULL OR c.dthNascimento <  DATE_ADD(DthNascimentoFim, INTERVAL 1 DAY))\n\n        AND (SemEmail IS NULL OR (SemEmail = 1 AND (c.Email IS NULL OR TRIM(c.Email) = '')))\n\n        AND (AniversariantesDoMes IS NULL OR\n\n             (AniversariantesDoMes = 1 AND c.dthNascimento IS NOT NULL\n\n              AND MONTH(c.dthNascimento) = MONTH(NOW())))\n\n    ORDER BY c.Nome;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
